-- The notable-NPC gap, second part: the named spirits and gods of Rifts World
-- Book 15: Spirit West - rows for notable_npcs (migration 072) and their attacks
-- in stat_attacks (owner_kind 'notable_npc').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- Phase 2b imported the gods of Pantheons of the Megaverse and Dragons and Gods;
-- Spirit West's were never taken. Here are the Four Kachina Godlings (printed
-- p.149), the five named Great Spirits (Old Flame Dancing, Ever Tide, Standing
-- Mountain, Uktena, Whispering Maiden; p.161-172) and the seven gods (Beautiful
-- Rock Dancer, Bright Sky, He Who Gives Life, She Who Walks The Circle, Strong
-- Eagle, Spider Woman, the God Thunderbird; p.173-189).
--
-- NOT HERE: the Nunnehi (p.151), headed as a Greater Spirit NPC but stated as a
-- race in dice; the kinds of spirit (Great Kachinas, Great Little Ones, elemental
-- and totem spirits), which are in creatures.
--
-- A SPIRIT'S POOLS: the book gives Great Spirits and gods hit points and S.D.C.,
-- and says that on Rifts Earth their M.D.C. is the two combined; the pools are
-- stored as printed and the rule is in bonuses_note. The Godlings print only
-- their own attributes and levels; their pools are the Great Kachina formulas
-- (p.147-148), in bonuses_note.
--
-- EXTRACTED by book-extract-workers; RECONCILED by book-reconcile against 200 dpi
-- renders, row by row - one worker read the text layer, so its five rows were
-- checked number by number on the image. The corrections are applied.
-- description, disposition and natural_abilities are short paraphrases, checked
-- against the cache by an 8-word shingle test - no sentence is the book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-notable-npcs-spirit-west.sql
--
-- BY BOOK:
--   Rifts World Book 15: Spirit West (16): Kacha-Nesha, Kacha-Ani, Kachir-Hadu,
--     Kachir-Nil, Old Flame Dancing, Ever Tide, Standing Mountain, Uktena, Whispering
--     Maiden, Beautiful Rock Dancer, Bright Sky, He Who Gives Life, She Who Walks The
--     Circle, Strong Eagle, Spider Woman, The God Thunderbird

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kacha-nesha', 'Kacha-Nesha', NULL, NULL, 'rifts', 'Great Kachina Spirit (water)', NULL, 12, 'Scrupulous', NULL, '10 feet (3 m)', NULL, '{"IQ":24,"ME":25,"MA":20,"PS":30,"PP":28,"PE":26,"PB":27,"Spd":38}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Water bonuses (p.149, applies to all Great Kachina Water Spirits): +3 on initiative, +1 to strike and parry, +2 to dodge, +4 to pull punch, +1 to save vs magic, +5 to save vs horror factor. The godling entry says all other powers, abilities, psionics, and magic are as printed above at the godling level, pointing to the generic Great Kachina Spirit block (p.147-148): S.D.C. P.E. x20, M.D.C. equal to combined HP+SDC when materialized on Rifts Earth, P.P.E. P.E. x20 +50 per level, I.S.P. M.E. x5 +12 per level, Horror Factor 14, 6 attacks/actions per melee in physical form (2 spells or 4 psionic attacks in energy form). Damage is as per supernatural P.S. attribute, psionics or magic - no separate weapon damage printed. Hit Points formula for water specifically: P.E. x50 +100 per level.', NULL, 'R.C.C. skills follow the generic Great Kachina Water Spirit list (p.148, as printed above): swim, boat building, pilot sail/row boats, navigation, astronomy, brewing, lore: cattle/animals, lore: Indians, lore: demons and monsters, all at 80% +2% per level; magically speaks all languages at 92%.', 'As per all spirits, with exceptions/additions printed for the four godlings (p.149): materializes into a human-sized Kachina Doll or any human form, male or female; can possess any animal or a willing Kachina Dancer; can summon spirits at three times the rate of a typical Great Kachina Spirit.', 'Knows all Warlock Water spells (per the generic element list, p.148); can create all minor and major fetishes, though sparingly.', 'Per the generic Great Kachina Water Spirit list (p.148): telepathy, hydro-kinesis, electro-kinesis, mind block auto-defense, and 1D4+2 psi-powers from the healing category.', NULL, NULL, NULL, NULL, 'Scrupulous; serves Standing-Mountain and Hard-Woman-Dancing as one of their four godling aides, a go-between for the gods and the Native peoples they guard.', 'Other spirits (lesser and greater), Native American gods, and Native Americans generally, especially Pure Ones and devoted Traditionalists; also dragons and occasionally alien intelligences (generic Great Kachina Spirit list, p.149).', 'Rival forces, gods, and enemies (generic Great Kachina Spirit list, p.149).', 'Water godling among the Four Kachina Godlings (12th level): light-blue skin, deep green eyes and hair that moves like water.', 'Rifts World Book 15: Spirit West p.149');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kacha-ani', 'Kacha-Ani', NULL, NULL, 'rifts', 'Great Kachina Spirit (fire)', NULL, 11, 'Scrupulous', NULL, '10 feet (3 m)', NULL, '{"IQ":21,"ME":20,"MA":28,"PS":27,"PP":30,"PE":24,"PB":29,"Spd":77}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Fire bonuses (p.149, applies to all Great Kachina Fire Spirits): +2 attacks per melee round, +5 on initiative, +3 to strike, +1 to pull punch, +1 to save vs magic, +10 to save vs horror factor. The godling entry says all other powers, abilities, psionics, and magic are as printed above at the godling level, pointing to the generic Great Kachina Spirit block (p.147-148): S.D.C. P.E. x20, M.D.C. equal to combined HP+SDC when materialized on Rifts Earth, P.P.E. P.E. x20 +50 per level, I.S.P. M.E. x5 +12 per level, Horror Factor 14, 6 attacks/actions per melee in physical form (2 spells or 4 psionic attacks in energy form). Damage is as per supernatural P.S. attribute, psionics or magic - no separate weapon damage printed. Hit Points formula: P.E. x50 (the book states an addition only for water, +100 per level, and Earth, +200 per level; none is stated for fire).', NULL, 'R.C.C. skills follow the generic Great Kachina Fire Spirit list (p.148, as printed above): land navigation, basic mathematics, interrogation, acrobatics, dance, sing, cook, climb, lore: Indians, lore: magic, lore: demons and monsters, all at 80% +2% per level; magically speaks all languages at 94%.', 'As per all spirits, with exceptions/additions printed for the four godlings (p.149): materializes into a human-sized Kachina Doll or any human form, male or female; can possess any animal or a willing Kachina Dancer; can summon spirits at three times the rate of a typical Great Kachina Spirit.', 'Knows all Warlock Fire spells (per the generic element list, p.148); can create all minor and major fetishes, though sparingly.', 'Per the generic Great Kachina Fire Spirit list (p.148): telepathy, object read, pyro-kinesis, mind bolt, hypnotic suggestion, mind block auto-defense, plus 1D4 psi-powers of choice from the sensitive category.', NULL, NULL, NULL, NULL, 'Scrupulous; serves Standing-Mountain and Hard-Woman-Dancing as one of their four godling aides, a go-between for the gods and the Native peoples they guard.', 'Other spirits (lesser and greater), Native American gods, and Native Americans generally, especially Pure Ones and devoted Traditionalists; also dragons and occasionally alien intelligences (generic Great Kachina Spirit list, p.149).', 'Rival forces, gods, and enemies (generic Great Kachina Spirit list, p.149).', 'Fire godling among the Four Kachina Godlings (11th level): red-skinned and yellow-eyed, with flames for hair - lovely and frightening at once.', 'Rifts World Book 15: Spirit West p.149');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kachir-hadu', 'Kachir-Hadu', NULL, NULL, 'rifts', 'Great Kachina Spirit (Earth)', NULL, 12, 'Principled', NULL, '10 feet (3 m)', NULL, '{"IQ":23,"ME":26,"MA":24,"PS":56,"PP":26,"PE":30,"PB":20,"Spd":50}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Earth bonuses (p.149, applies to all Great Kachina Earth Spirits): +1 attack per melee round, +2 on initiative, +2 to strike, +4 to pull punch, +1 to save vs magic, +6 to save vs horror factor. The godling entry says all other powers, abilities, psionics, and magic are as printed above at the godling level, pointing to the generic Great Kachina Spirit block (p.147-148): S.D.C. P.E. x20, M.D.C. equal to combined HP+SDC when materialized on Rifts Earth, P.P.E. P.E. x20 +50 per level, I.S.P. M.E. x5 +12 per level, Horror Factor 14, 6 attacks/actions per melee in physical form (2 spells or 4 psionic attacks in energy form). Damage is as per supernatural P.S. attribute, psionics or magic - no separate weapon damage printed. Hit Points formula for Earth specifically: P.E. x50 +200 per level.', NULL, 'R.C.C. skills follow the generic Great Kachina Earth Spirit list (p.148, as printed above): all wilderness skills plus botany, breed dogs, animal husbandry, holistic medicine, wilderness survival, climb, basic mathematics, lore: animals and cattle, lore: magic/geomancy/ley lines, lore: Indians, lore: demons and monsters, all at 80% +2% per level; magically speaks all languages at 96%.', 'As per all spirits, with exceptions/additions printed for the four godlings (p.149): materializes into a human-sized Kachina Doll or any human form, male or female; can possess any animal or a willing Kachina Dancer; can summon spirits at three times the rate of a typical Great Kachina Spirit.', 'Knows all Warlock Earth spells (per the generic element list, p.148); can create all minor and major fetishes, though sparingly.', 'Per the generic Great Kachina Earth Spirit list (p.148): telepathy, bio-manipulation, P.P.E. shield, mind block auto-defense, group mind block, plus 1D4 psi-powers from the physical category.', NULL, NULL, NULL, NULL, 'Principled; serves Standing-Mountain and Hard-Woman-Dancing as one of their four godling aides, a go-between for the gods and the Native peoples they guard.', 'Other spirits (lesser and greater), Native American gods, and Native Americans generally, especially Pure Ones and devoted Traditionalists; also dragons and occasionally alien intelligences (generic Great Kachina Spirit list, p.149).', 'Rival forces, gods, and enemies (generic Great Kachina Spirit list, p.149).', 'Earth godling among the Four Kachina Godlings (12th level): a towering Kachina Dancer figure wearing a mask of stone.', 'Rifts World Book 15: Spirit West p.149');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kachir-nil', 'Kachir-Nil', NULL, NULL, 'rifts', 'Great Kachina Spirit (Air)', NULL, 13, 'Unprincipled', NULL, '10 feet (3 m)', NULL, '{"IQ":25,"ME":23,"MA":24,"PS":51,"PP":30,"PE":25,"PB":28,"Spd":220}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Air bonuses (p.149, applies to all Great Kachina Air Spirits): +1 attack per melee round, +4 on initiative, +4 to dodge, +2 to pull punch, +1 to save vs magic, +5 to save vs horror factor. The godling entry says all other powers, abilities, psionics, and magic are as printed above at the godling level, pointing to the generic Great Kachina Spirit block (p.147-148): S.D.C. P.E. x20, M.D.C. equal to combined HP+SDC when materialized on Rifts Earth, P.P.E. P.E. x20 +50 per level, I.S.P. M.E. x5 +12 per level, Horror Factor 14, 6 attacks/actions per melee in physical form (2 spells or 4 psionic attacks in energy form). Damage is as per supernatural P.S. attribute, psionics or magic - no separate weapon damage printed. Hit Points formula: P.E. x50 (the book states an addition only for water, +100 per level, and Earth, +200 per level; none is stated for air).', NULL, 'R.C.C. skills follow the generic Great Kachina Air Spirit list (p.148, as printed above): astronomy, navigation, land navigation, basic and advanced mathematics, chemistry, intelligence, surveillance: tailing, detect concealment, detect ambush, concealment, palming, pick pocket, escape artist, prowl, and all lore, all at 80% +2% per level; magically speaks all languages at 96%.', 'As per all spirits, with exceptions/additions printed for the four godlings (p.149): materializes into a human-sized Kachina Doll or any human form, male or female; can possess any animal or a willing Kachina Dancer; can summon spirits at three times the rate of a typical Great Kachina Spirit.', 'Knows all Warlock Air spells (per the generic element list, p.148); can create all minor and major fetishes, though sparingly.', 'Per the generic Great Kachina Air Spirit list (p.148): telepathy, empathy, empathic transmission, telekinesis (super), mind block auto-defense, plus 1D4 psi-powers of choice from the sensitive category.', NULL, NULL, NULL, NULL, 'Unprincipled - more self-serving than the other three, yet still one of the four godling aides of Standing-Mountain and Hard-Woman-Dancing.', 'Other spirits (lesser and greater), Native American gods, and Native Americans generally, especially Pure Ones and devoted Traditionalists; also dragons and occasionally alien intelligences (generic Great Kachina Spirit list, p.149).', 'Rival forces, gods, and enemies (generic Great Kachina Spirit list, p.149).', 'Air godling among the Four Kachina Godlings (13th level): a huge warrior with red-clay skin, bright blue eyes and black-and-white feathers for hair.', 'Rifts World Book 15: Spirit West p.149');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'old-flame-dancing', 'Old Flame Dancing', NULL, 'Great Fire Elemental Spirit', 'rifts', NULL, '18th level Elemental Shaman (Fire), 10th level Military Specialist', 18, 'Unprincipled', 'Immortal, but can be destroyed while in energy form', 'Either a 25 ft (7.5 m) tall humanoid or a 40 ft (12 m) snake, both covered in flames', '2,000 lb.', '{"IQ":22,"ME":25,"MA":21,"PS":40,"PP":27,"PE":28,"PB":20,"Spd":88}', 7700, 6200, NULL, 3690, 651, 16, 17, '{"attacks":8,"initiative":7,"strike":9,"parry":14,"dodge":14,"roll":4}', 'In physical form 8 physical/psionic attacks or 2 by magic per melee; in energy form 2 magic spells or 6 psionic attacks/other actions. +25 to S.D.C. damage, critical strike from behind or on 18+, knockout from behind or on 18+, death blow on 18+, paired weapons, +6 save vs horror factor, +10 save vs magic, +12 vs magic illusions, +5 save vs psionic attacks, +7 save vs poison. Mega-Damage Creature note: when materialized on Rifts Earth, M.D.C. equals combined Hit Points plus S.D.C. (no separate M.D.C. figure printed). Vulnerabilities: cold and water-based attacks/magic do double damage.', '[{"name":"Basic Mathematics","pct":88},{"name":"Advanced Mathematics","pct":88},{"name":"Chemistry","pct":88},{"name":"Streetwise","pct":88},{"name":"Pick Locks","pct":88},{"name":"Concealment","pct":88},{"name":"Radio: Basic","pct":88},{"name":"Seduction","pct":88},{"name":"Interrogation","pct":88},{"name":"Cardsharp","pct":88},{"name":"Find Contraband","pct":88},{"name":"Recognize Weapon Quality","pct":88},{"name":"Military Fortifications","pct":88},{"name":"Horsemanship: Cowboy","pct":88},{"name":"Brewing","pct":88},{"name":"Language: All Languages (magical)","pct":98}]', 'All skills from the categories of Espionage and Wilderness at 92% (category grant, not individually named). All lore skills at 88%. W.P. Energy Rifle (10th level; favors plasma weapons) and W.P. Energy Heavy (10th level) - no percentage printed.', 'Nightvision 2,000 ft; bio-regeneration 1D6x10 per melee round; flight to 200 mph; impervious to heat/fire (even magic and M.D. plasma), smoke, gases, disease. Materializes as an ordinary Copperhead Rattlesnake, a human, or a giant flaming human/snake (24 hrs/level, 50 P.P.E./day). Can possess snakes or willing/comatose humans (adds 1D6x1000 S.D.C. to host). Summons True Fire Elementals and Lesser Elemental Spirits. Thermal optics/sensors out to 5,000 ft.', 'All Warlock fire spells and all Shamanic Magic, plus negate magic, transferal, mystic portal, close Rift, and dimensional portal. Spell strength 16. Can create all lesser and major fetishes plus the Legendary Serpent Fetish.', 'All physical and super psionics, plus Mega-Pyrokinesis (as the super psionic ability but x6 range, damage and area of effect)', NULL, NULL, NULL, NULL, 'Passionate and generous toward those he favors, but intense, impulsive, self-indulgent with food, drink and festivities, and unshakably loyal to friends and causes even past the point of prudence.', 'Other spirits (lesser and greater), some Native American Gods, and Native American people generally, particularly Pure Ones and devoted Traditionalists.', 'The forces of evil, dark spirits, evil Shamans, supernatural monsters, rivals and enemies of the Native Americans; the Coalition States and other human supremacists.', 'Old Flame Dancing is an ancient Native American fire spirit bordering on godhood, a champion of Native Americans and sworn enemy of human supremacists like the Coalition States.', 'Rifts World Book 15: Spirit West p.161-163');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'ever-tide', 'Ever Tide', NULL, 'Great Water Elemental Spirit', 'rifts', NULL, '17th level Elemental Shaman (Water), 10th level Water Warlock', 17, 'Anarchist in the sense of chaos, change and contradiction', 'Immortal, but can be destroyed while in energy form', 'Varies with his chosen form: human-sized, a 30 foot (9 m) crocodile, or a 150 foot (45.7 m) long and 30 foot (9 m) tall crocodile seemingly made of crystal clear water', '10 tons as water crocodile, half a ton as normal-looking crocodile, and 100-200 pounds (45 to 90 kg) as a human', '{"IQ":18,"ME":25,"MA":20,"PS":70,"PP":24,"PE":28,"PB":20,"Spd":30}', 9800, 9000, NULL, 3200, 500, 17, 18, '{"attacks":6,"initiative":4,"strike":6,"parry":8,"dodge":6,"roll":4}', 'In physical form 6 physical/psionic attacks or 2 by magic per melee; in energy form 2 magic spells or 5 psionic attacks/other actions. Critical strike on 18+, knockout on 18+, death blow, paired weapons, leap attack, +10 save vs horror factor, +10 save vs magic, spell strength 16, +5 save vs psionics, +7 save vs poison. Mega-Damage Creature note: when materialized, M.D.C. equals combined Hit Points plus S.D.C. (no separate figure printed). Vulnerabilities: mega-damage energy blasts, heat, fire, magic heat and explosions do double damage; electricity does half damage.', '[{"name":"Swim","pct":94},{"name":"Track Humanoids","pct":80},{"name":"Climb","pct":80},{"name":"Holistic Medicine","pct":80},{"name":"Prowl","pct":80},{"name":"Camouflage","pct":80},{"name":"Language: All Languages (magical)","pct":90}]', 'All skills from the categories of Wilderness and Rogue at 94% (category grant). All lore skills at 80%.', 'Nightvision 6,000 ft; bio-regeneration 1D6x10 per melee round; travels through cracks/openings like water and underwater at up to 200 mph (energy/water form only); impervious to disease, normal cold and ocean depths; electricity does half damage. Water Speak: reads chemicals/minerals/disturbances in water at 90%, predicts tidal waves/storms at 80%. Materializes as a giant water crocodile, any aquatic reptile, or a human (12 hrs/level, 100 P.P.E./day); preferred form is a 150 ft crocodile of living water, impervious to projectiles, double damage from mega-damage/magical fire, can ooze through any non-airtight structure, shatters S.D.C. structures. Bite 2D4x10, tail slash 2D6x10 (M.D. or S.D.C. by environment). Possesses aquatic reptiles (not humans), adding 1D6x1000 S.D.C. to host and doubling swim speed. Summons True Water Elementals and Lesser Elemental Spirits.', 'All water Warlock magic (10th level) and conventional spells levels 1-8, plus water to wine, banishment, time hole, close Rift, and Dimensional Portal. Can create all lesser fetishes plus the major fetishes Great Tracking and Great Tooth and Claw.', 'All sensitive abilities plus hydrokinesis (triple range and duration, double damage), electrokinesis (double range), and bio-manipulation', NULL, NULL, NULL, NULL, 'Volatile, self-serving, fickle and chaotic; swings between sudden cruelty and unexpected kindness, and enjoys watching others struggle and suffer.', 'Makes many temporary alliances with both good and evil, human and demonic, depending on his current mood and goals; the Splugorth of Atlantis (via Splynncryth) are a regular ally and business associate, and he is close with the Great Dark Spirit Uktena.', NULL, 'Ever Tide is the Great Water Elemental Spirit of fluidity, change and chaos, an unpredictable ally and enemy to both mortals and gods.', 'Rifts World Book 15: Spirit West p.164-166');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'standing-mountain', 'Standing Mountain', NULL, 'Great Earth Elemental Spirit', 'rifts', NULL, '18th level Elemental Shaman (Earth), 10th level Earth Warlock', 18, 'Principled', 'Immortal, but can be destroyed while in energy form', '7 feet (2.1 m) in human form', '315 pounds (141.7 kg)', '{"IQ":18,"ME":20,"MA":25,"PS":60,"PP":17,"PE":32,"PB":17,"Spd":24}', 8400, 5800, NULL, 4300, 800, 18, 15, '{"attacks":7,"initiative":3,"strike":3,"parry":4,"dodge":4,"roll":4}', 'In physical form 7 physical/psionic attacks or 2 by magic per melee; in energy form 2 magic spells or 6 psionic attacks/other actions. Critical strike from behind or on 18+, knockout from behind or on 19+, +10 save vs horror factor, +10 vs magic, spell strength 16, +3 save vs psionics, +9 save vs poison. Horror Factor is 15 only when his true identity is realized. Mega-Damage Creature note: when materialized, M.D.C. equals combined Hit Points plus S.D.C. (no separate figure printed). Vulnerabilities: water-based magic does 50% more damage; his rigid, uncompromising views make him a difficult ally.', '[{"name":"Climb","pct":90},{"name":"Swim","pct":90},{"name":"Holistic Medicine","pct":90},{"name":"Animal Husbandry","pct":90},{"name":"Horsemanship: Knight","pct":90},{"name":"Camouflage","pct":90},{"name":"Prospecting","pct":90},{"name":"Armorer","pct":90},{"name":"Military Fortification","pct":90},{"name":"Recognize Weapons","pct":90},{"name":"Trap Construction","pct":90},{"name":"Trap Detection","pct":90},{"name":"Breed Dogs","pct":90},{"name":"Ventriloquism","pct":90},{"name":"Language: All Languages (magical)","pct":95}]', 'All skills from the categories of Wilderness and Science at 98% (category grant). All lore skills at 90%.', 'Nightvision 2,000 ft; bio-regeneration 1D6x10 per melee round; travels through earth as if flying through air at up to 200 mph (energy form only); impervious to disease and normal cold/heat/fire; magic heat/fire/cold spells do half damage; other energy attacks do full damage. Earth Speak: identifies minerals and senses seismic disturbances within 200 miles at 96%, predicts earthquakes/hazards at 90%. Materializes as a muscular Native American or a bear-sized giant badger (24 hrs/level, 50 P.P.E./day). Possesses (inhabits) large/giant stones, earth mounds, or sand dunes at will and at no P.P.E. cost, can speak, cast spells and use psionics but not fight physically while possessing. Summons True Earth Elementals and Lesser Elemental Spirits.', 'All Earth Warlock magic (10th level), all Shamanic plant and paradox spells, and conventional spells levels 1-5, plus dispel magic barriers, negate magic, cure sickness, spoil, purification (food and water), restoration, create golem, close Rift, and Dimensional Portal. Can create all lesser fetishes plus the major fetishes Great Armor, Great Body, Great Tracking, Shapechange, Supernatural Damage, Great Tooth and Claw and Great Weapons, plus the Legendary Fetishes Dragon Bone Armor and Spirit Weapons (all).', 'All physical psionics plus object read, presence sense, see aura, bio-manipulation, telekinesis (super), telekinetic force field, telemechanics, mind block auto-defense, and group mind block', NULL, NULL, 'Always carries a war club that, struck against the ground, summons a Lesser Earth Elemental Spirit or opens a chasm.', NULL, 'Stoic, secretive and difficult to anger; rarely interacts with humans or other spirits unless directly petitioned, and judges those who bring wrongdoing on themselves harshly.', 'Other spirits (lesser and greater) and some Native American Gods, as well as Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The forces of evil, dark spirits, evil Shamans, supernatural monsters, rivals and enemies of the Native Americans.', 'Standing Mountain is the Great Earth Elemental Spirit of soil and stone, a principled but distant figure who only acts when specifically asked or when a grave wrong upsets the balance of things.', 'Rifts World Book 15: Spirit West p.166-167');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'uktena', 'Uktena', NULL, 'Great Dark Serpent', 'rifts', NULL, '22nd level Ley Line Walker, 13th level Water Warlock', 22, 'Miscreant', 'Immortal, but can be destroyed while in energy form', '30 ft tall (9 m) and 75 ft long (22.5 m)', '32 tons', '{"IQ":19,"ME":19,"MA":22,"PS":45,"PP":21,"PE":30,"PB":6,"Spd":60}', 11600, 9500, NULL, 7200, 560, 17, 17, '{"attacks":7,"initiative":5,"strike":6,"parry":8,"dodge":8,"roll":5}', 'In physical form 7 physical/psionic attacks or 3 by magic per melee; in energy form 2 magic spells or 6 psionic attacks/other actions. Critical strike from behind or on 18+, knockout from behind or on 17+, +10 save vs horror factor, +6 save vs magic, spell strength 17, +6 save vs psionics, +8 save vs poison. Speed is 60 on land and 160 swimming (approx. 100 mph/160 km). Mega-Damage Creature note: when materialized, M.D.C. equals combined Hit Points plus S.D.C. (no separate figure printed). Vulnerabilities: M.D. and magical fires do double damage; electricity does half damage; explosives, most energy weapons and rail guns do normal damage. Insanities: paranoia, borderline obsessive need for revenge, borderline obsessive greed, megalomania, sadism, and a need to prove his power by manipulating and hurting others.', '[{"name":"Basic Mathematics","pct":96},{"name":"Swim","pct":96},{"name":"Prowl","pct":85},{"name":"Literacy: Native American Languages (including Mayan and Aztec)","pct":85},{"name":"Literacy: English","pct":85},{"name":"Literacy: Dragonese","pct":85},{"name":"Language: All Languages (magical)","pct":90}]', 'All skills from the categories of Wilderness, Espionage, and Rogue at 96% (category grant). All lore skills at 85%.', 'Dowsing (as the spell, triple range); nightvision 6,000 ft; sees through fog/mist without impairment; impervious to ocean depths, tidal waves, lightning, cold, and disease; bio-regeneration 2D6x10 per melee round. Materializes as any bird, mammal, human, humanoid D-bee, or dragon (22 days per materialization, 50 P.P.E./day); can metamorph into virtually any bird/mammal/humanoid/dragon shape for up to 11 days at a time. Water Speak: identifies chemicals/minerals/disturbances in water at 90%, predicts tidal waves/storms at 80%, senses currents/tides/weather at 90%. Possesses birds, mammals, or willing humans (worshipers/minions), adding 2D4x1000 S.D.C. to host and doubling its speed. Summons True Lesser Water/Air Elementals and Greater Water/Air Elementals, and can summon/teleport Ukt Water Serpents to him.', 'All Ley Line Walker abilities and spells levels 1-15, all water elemental spells levels 1-8, and all Shamanic Spirit and Paradox spells. Can create all lesser and major fetishes plus the Legendary Fetishes Metamorphosis, Serpent, Sweat Lodge, and Spirit Weapons (all).', 'All healing, sensitive and super-psionic abilities', NULL, NULL, NULL, NULL, 'Paranoid, envious, vengeful, manipulative and sadistic, but calculating enough to act indirectly so as not to provoke the other gods.', 'The forces of darkness and any willing to accept him as master, including the vampires of Mexico, the Splugorth, Ever Tide, demon lords, ancient dragons, evil sorcerers and murderous madmen.', 'All who stand in his way, and those who will not acknowledge him as the greatest of all gods and lord of all spirits.', 'Uktena is the Great Dark Serpent, an ancient chaotic spirit corrupted into one of the strongest forces of evil in the Native American pantheon, tempting mortals and gods alike toward ruin.', 'Rifts World Book 15: Spirit West p.168-170');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'whispering-maiden', 'Whispering Maiden', NULL, 'Goddess of the Winds', 'rifts', NULL, '20th level Elemental Shaman (Air), 10th level Air Warlock', 20, 'Unprincipled', 'Immortal, but can be destroyed while in energy form', 'Varies with the form she takes; either an average sized Native American woman (about 5 ft, 7 inches/1.48 m) or a falcon', 'Varies with her chosen form; about 120 pounds as a human female', '{"IQ":24,"ME":22,"MA":27,"PS":28,"PP":30,"PE":23,"PB":28,"Spd":88}', 6800, 5200, NULL, 4000, 625, 16, 15, '{"attacks":8,"initiative":7,"strike":9,"parry":10,"dodge":10,"roll":4}', 'In physical form 8 physical/psionic attacks or 2 by magic per melee; in energy form 2 magic spells or 7 psionic attacks/6 other actions. Critical strike from behind or on 19+, knockout from behind, +6 save vs horror factor, +8 vs magic, spell strength 16, +4 save vs psionics and poison. Horror Factor 15 only when her true identity is realized. Speed 88 (60 mph/96 km) on the ground when materialized; can also float, hover and fly in all manifestations. Mega-Damage Creature note: when materialized, M.D.C. equals combined Hit Points plus S.D.C. (no separate figure printed). Vulnerabilities: when materialized or possessing, lightning and electrical attacks do no damage but cause discomfort and confusion, a single blast reduces her attacks per melee by one and skill performance by -10% for the rest of that round, cumulative with multiple attacks; her aloofness and tendency to hang back too long can work against her.', '[{"name":"Basic Mathematics","pct":90},{"name":"Advanced Mathematics","pct":90},{"name":"Astronomy","pct":90},{"name":"Streetwise","pct":90},{"name":"Surveillance","pct":90},{"name":"Trap Detection","pct":90},{"name":"Camouflage","pct":90},{"name":"Find Contraband","pct":90},{"name":"Ventriloquism","pct":90},{"name":"Language: All Languages (magical)","pct":98}]', 'All skills from the categories of Espionage and Wilderness at 98% (category grant). All lore skills at 90%.', 'Nightvision 6,000 ft; keen vision (sees five miles); bio-regeneration 1D6x10 per melee round; impervious to heat, cold, gases and disease. Knows time of day, wind direction and approach of storms at 90%; senses impurities, smoke, fire and chemicals in the air at 80%. Wingless Flight up to Mach 1 (675 mph), max altitude 15,000 ft, no P.P.E. cost. Invisibility at Will (superior form; cannot attack or cast spells while invisible, but can use psionics). Possess the Wind: becomes the wind itself, up to 200 mph (spies as a breeze under 5 mph), controls its direction/angle/height/speed up to 40 mph; cannot attack or cast spells in this form, but can use psionics; no P.P.E. cost. Can scatter or carry off light items (1D6x10 yards per melee action; victim must roll to strike/grab, she rolls to dodge). Materializes as an ordinary falcon or a young Native American woman (24 hrs/level, 50 P.P.E./day). Possesses birds of prey (not humans), adding 1D6x1000 S.D.C. to host and doubling its flying speed. Summons True Air Elementals and Lesser Air Elemental Spirits.', 'All air elemental spells plus all Shamanic spirit spells, magic pigeon, dispel magic barriers, negate magic, wisps of confusion, anti-magic cloud, sanctum, close Rift, Dimensional Portal, and teleport: superior. Can create all lesser fetishes plus the major fetishes Great Song, Great Weapons, and Wing Flight, plus the Legendary Fetishes Spirit Weapon: Bow, Spirit Weapon: Spear, Spirit Wing and Wind-Rider.', 'All sensitive psionic abilities plus empathic transmission, mind bolt, mentally possess others, electrokinesis, hydrokinesis, and telemechanics', NULL, NULL, 'A bow and arrows that are powerful fetishes (a Legendary Spirit Weapon: Bow); usually accompanied by a falcon who is a greater animal spirit, her constant companion and servant.', NULL, 'Elusive, watchful and aloof, preferring to observe unseen rather than intervene directly; her rare bursts of fury are as sudden and overwhelming as a storm.', 'Other spirits (lesser and greater) and some Native American Gods, as well as Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The forces of evil, dark spirits, evil Shamans, supernatural monsters, rivals and enemies of the Native Americans.', 'Whispering Maiden is the Great Spirit goddess of the winds, who travels the world unseen watching and listening, and warns favored mortals through whispers on the breeze.', 'Rifts World Book 15: Spirit West p.170-172');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'beautiful-rock-dancer', 'Beautiful Rock Dancer', NULL, 'The Goddess of Ice and Valuable Minerals', 'rifts', NULL, '30th level Elemental Shaman (Water), 20th level Ley Line Walker, and a 15th level Fetish Shaman', 30, 'Principled', 'Immortal, but can be destroyed while in energy form.', '5 feet, 6 inches in human form', '125 pounds (56 kg)', '{"IQ":23,"ME":22,"MA":28,"PS":18,"PP":25,"PE":21,"PB":30,"Spd":29}', 6700, 5400, NULL, 5700, 650, 11, 15, '{"initiative":2,"strike":5,"parry":8,"dodge":8,"roll":4}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals her combined H.P. + S.D.C.; spirits in energy form carry the same M.D.C. total. All physical attributes are supernatural. Combat Attacks per Melee: in energy form, two magic spells or six psionic attacks/six other actions per melee; in physical humanoid form, seven physical and/or psionic attacks/actions per melee, or two by magic. Bonuses (book''s own total bonuses): +7 to strike with weapons (in addition to the +5 to strike above); roll with impact, critical strike or knockout on 18+; +6 save vs horror factor; +5 save vs magic and poison; spell strength 16; +4 save vs psionics.', '[{"name":"Master Jeweler (identify/value minerals, cut/shape gems and crystal, make jewelry)","pct":98}]', 'All skills from the Wilderness category and all lore skills at 98%; plus climb, swim, art, dance, sing, cook, sew, holistic medicine, basic and advanced math, astronomy, history, animal husbandry, horsemanship: exotic animals, camouflage, prospecting, find contraband, recognize weapons, trap construction, trap/mine detection, sculpt/whittle, and seduction, all at 90% (several of these skills are from Rifts New West). Magically understands and speaks all languages at 98%; literate in all Native American languages, Spanish and Dragonese. O.C.C.: Not applicable.', 'Nightvision 2,000 ft; bio-regeneration 1D6x10/melee round; flight to 200 mph; impervious to cold (even magic cold) and disease; resistant to fire (half damage). Materialization into an ordinary human or a giant (to 30 ft) crystal Native American woman, icy cold to the touch, able to lower temperature 50 degrees in a 1 mile radius (see attacks). Possession of any gemstone/crystal/standing stone (automatic) or willing worshippers/comatose humans; adds 2D6x1000 S.D.C. to a possessed creature. Summons True Water/Earth Elementals and Elemental Spirits (Lesser or Greater).', 'Earth and water elemental spells levels 1-4; all Shamanic Spirit spells; all conventional spells levels 1-5; plus apparition, mask of deceit, time slip, dispel magic barrier, hallucination, oracle, stone to flesh, water to wine, create magic scroll, amulet, talisman, close Rift, and dimensional portal. Can make, empower and bestow all fetishes, including Legendary, but sparingly.', 'All Sensitive, Healing and Super psionic abilities. Natural Telepath: unlimited use, no I.S.P. cost, 1 mile radius.', NULL, NULL, 'Walking stick that is a Legendary Weapon fetish; usually carries two major healing fetishes and a number of minor fetishes.', NULL, 'Regal, remote and cold as the ice and crystal she stands for; proud and vain, she undervalues her foes, rates herself too highly and has come to need worship. Wears southwestern dress with silver and lapis. Lives in the Spirit Realm, most often visiting North America.', 'Other Native American gods and spirits (lesser and greater), and Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The forces of evil, dark spirits, evil Shamans, supernatural monsters, and rivals/enemies of the Native Americans.', 'Goddess of ice and valuable minerals, wife of Bright Sky, and patron of craftsmen, jewelers and mortal women.', 'Rifts World Book 15: Spirit West p.173-175');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'bright-sky', 'Bright Sky', NULL, 'The Sun God', 'rifts', NULL, '25th level Ley Line Walker and Warrior, and 15th level Warlock (air and fire)', 25, 'Scrupulous', 'Immortal, but can be destroyed while in energy form.', '6 feet, 6 inches (1.9 m) in human form', '200 lbs. (90 kg) in human form', '{"IQ":18,"ME":20,"MA":23,"PS":35,"PP":24,"PE":26,"PB":20,"Spd":44}', 8500, 7100, NULL, 6500, 700, 14, 17, '{"initiative":8,"strike":8,"parry":12,"dodge":12,"roll":6,"pull":10}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals his combined H.P. + S.D.C. All physical attributes are supernatural. Spd 44 on the ground (30 mph/48 km); can also float, hover and fly up to Mach 6. Combat Attacks per Melee: in energy form, two magic spells or eight psionic attacks/eight other actions per melee; in physical humanoid form, 10 physical and/or psionic attacks/actions per melee, or two by magic. Bonuses printed as a single ''total bonuses'' list (this NPC''s own stat block, on the page shared with He Who Gives Life''s narrative): critical strike or knockout from behind and on 17+; +10 save vs horror factor; +7 save vs magic; spell strength 17; +3 save vs psionics; +8 save vs poison. Bullets, punches, rail gun rounds, missiles and explosives all do normal damage to him; he loves conflicts with foes worthy of his power (fellow gods, demon lords, alien intelligences).', NULL, 'All skills from the Wilderness, Espionage and Military categories at 97%, plus all lore skills, climb, swim, dance, sing, cook, basic and advanced math, astronomy, horsemanship: Cowboy, and horsemanship: exotic animals, all at 90% (several from Rifts New West). Magically understands/speaks all languages at 98%; literate in all Native American languages, Spanish and Dragonese. O.C.C.: Not applicable.', 'Keen hawk-like telescopic vision (10 mi), nightvision 6000 ft, sees all light spectrums, cannot be blinded by light; bio-regeneration 1D6x10/melee; flight to Mach 6; impervious to cold (even magic), vacuum, radiation, disease and lasers; resistant to fire and most energy blasts (half damage). Aura of Light in combat/flight (30 ft radius: save vs magic or be blinded; even a save gives -2 initiative/combat). Materialization into an ordinary human or a giant (to 30 ft) warrior, hot to the touch, skin like red clay; can raise temperature 70 degrees in a 1 mile radius. Possession of lesser elementals and birds of prey (except eagles) or bats, or willing worshippers/comatose humans; adds 2D6x1000 S.D.C. to a possessed creature. Summons True Fire/Air Elementals and Elemental Spirits (Lesser or Greater).', 'Fire and air elemental spells levels 1-5; all Shamanic Spirit and plant spells; all conventional spells levels 1-15. Can make, empower and bestow all minor, major and legendary Armor, Body, Strength, Tooth and Claw, and Weapon fetishes, but very sparingly.', 'All physical, sensitive, and super psionic abilities.', NULL, NULL, 'Bow and a long metal tomahawk (narrative) / Legendary Spirit Bow and Spirit Axe (his stat block''s Personal Fetishes line) -- each a Legendary Weapon fetish.', NULL, 'Guardian of the Spirit Realm who leaves mortals to their own affairs unless a great supernatural threat appears; comfortable with technology, he will carry high-tech or Techno-Wizard arms as readily as his own powers. Rarely visits the mortal world.', 'Other Native American gods, spirits (lesser and greater), and Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The Splugorth and all alien intelligences, forces of evil, dark spirits, evil Shamans, supernatural monsters, and rivals; counted among gods who see Uktena as a symbol of death, but hates the creature and frequently clashes with it.', 'The Sun God, husband of Beautiful Rock Dancer, who embodies air and fire and controls the weather.', 'Rifts World Book 15: Spirit West p.175-177');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'he-who-gives-life', 'He Who Gives Life', NULL, 'The God of Agriculture and Fertility', 'rifts', NULL, '24th level Plant Shaman, Healer and Deific Elemental Master (the latter equal to a 10th level Earth, Water and Air Warlock)', 24, 'Unprincipled', 'Immortal, but can be destroyed while in energy form.', '5 feet, 11 inches (1.79 m) in human form', '190 lbs. (87 kg) in human form', '{"IQ":23,"ME":22,"MA":26,"PS":25,"PP":24,"PE":30,"PB":20,"Spd":33}', 5300, 4200, NULL, 7100, 800, 14, 13, '{"initiative":5,"strike":3,"parry":8,"dodge":8,"roll":4,"pull":8,"disarm":5}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals his combined H.P. + S.D.C. All physical attributes are supernatural; Spd 33 is 22.5 mph/36 km. Combat Attacks per Melee: in energy form, two magic spells or six psionic attacks/six other actions per melee; in physical humanoid form, six physical and/or psionic attacks/actions per melee (typically defensive maneuvers), or two by magic. Critical strike or knockout from behind and on 17+; +8 save vs horror factor; +8 save vs magic; spell strength 16; +4 save vs psionics. Tolerance to alcohol equal to a Saloon Bum O.C.C. Some argue his pacifistic nature is a detriment to others and a personal weakness.', '[{"name":"Sense Elemental Forces (invisible spirits, Astral beings, True Elementals, Elemental Spirits and creatures linked to them, within 2000 ft)","pct":90},{"name":"Understand & Speak the language of True Elementals","pct":98}]', 'All skills from the Wilderness, Medicine and Science categories at 97%, plus all lore skills, climb, swim, dance, sing, cook, basic and advanced math, astronomy, herd cattle, roping, whittle, horsemanship: Cowboy, horsemanship: exotic animals and trick riding, all at 90% (several from Rifts New West). Magically understands/speaks all languages at 98%; literate in all Native American languages, Spanish and Dragonese. O.C.C.: Not applicable.', 'Nightvision 2,000 ft; bio-regeneration 2D4x10/melee; flight to 200 mph; impervious to disease, poisons, drugs and toxins; resistant to cold (half damage); all special powers of a Greater Earth Elemental Spirit. Plant Control and Influence: force a plant to blossom/bear 1-25 fruit in one melee (25x/plant/day); halt spoilage of food; accelerate plant/tree growth to full maturity overnight; shape wood like clay; convert wood to M.D.C. structure. Bless and Purify up to 10 acres of crops. Summons any lesser True Elemental (any of the four types) and Elemental Spirits (Lesser or Greater). Materialization into an aging Native American or a small nonpredatory animal (sparrow, mouse, mole, rabbit), or into a plant/shrub with Plant Spirit-like animation. Possession of small animals, plants or shrubs (rarely trees); adds 1D6x1000 S.D.C. to what he possesses; can speak/cast spells/use psionics even as a plant.', 'All Shamanic spells except Paradox; Earth, water and air Warlock spells levels 1-6; all healing spells (including restoration); all summon/control animal spells; plus sanctum, protection circles (lesser and superior), close Rift, and dimensional portal. Can create, empower and grant all lesser fetishes and noncombat major/Legendary fetishes, but never a weapon or war-inviting fetish.', 'All Healing, Sensitive, and Super psionic abilities.', NULL, NULL, 'Walking stick and Tomahawk, both Legendary Weapon fetishes (rarely used; he avoids fighting). One Legendary Healing fetish and a Medicine Bundle kept at his Spirit Realm village. Carries a dozen fetish masks in a magical pouch that appears to hold only one. Possesses the only known Legendary Fetish Mask, made from a Millennium Tree: can raise a ley line storm (half effect off a ley line, full effect per Rifts World Book Three: England rules if on one, disabling the mask for 36 hours after off-line use); grants 150 M.D.C. of mystical armor and +3 to all saves; camouflages the wearer as the Chameleon spell (3/day, no P.P.E.); makes the wearer impervious to natural disease/poison; and lets the wearer cast weather spells and all plant spells levels 1-15 (normal P.P.E. costs apply).', NULL, 'A gentle, wise, grandfatherly figure who lives as a village Shaman among mortals in the Spirit Realm, tends a hidden storehouse of every seed ever grown, and wanders Rifts Earth as a scout or farmer sharing food; will not kill and fights only when he must, preferring to subdue.', 'Other Native American gods, spirits (lesser and greater), and Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The Splugorth and all alien intelligences, forces of evil, dark spirits, evil Shamans, supernatural monsters, and rivals; lobbies against the destruction of Uktena, insisting death is part of the Circle of Life, change and renewal.', 'The god of agriculture and fertility, credited with fetish magic and the guardian of the Circle of Life.', 'Rifts World Book 15: Spirit West p.177-179');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'she-who-walks-the-circle', 'She Who Walks The Circle', NULL, 'Goddess of the dead and bringer of bad medicine', 'rifts', NULL, '12th level Paradox Shaman and 10th level Mystic Warrior', 12, 'Aberrant evil, with a strong sense of duty and honor, but who often extracts a terrible revenge; completely loyal to the Native American gods', 'Immortal, but can be destroyed while in energy form.', '6 feet (1.8 m) in human form', '150 lbs. (67.5 kg) in human form', '{"IQ":23,"ME":24,"MA":24,"PS":36,"PP":26,"PE":27,"PB":17,"Spd":50}', 4500, 3000, NULL, 2500, 326, 14, 14, '{"initiative":8,"strike":7,"parry":9,"dodge":9,"roll":3,"pull":4}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals her combined H.P. + S.D.C. All physical attributes are supernatural. Wearing her owl mask, costume and war paint raises her horror factor by 4 (to 18) while she carries out her duties. Combat Attacks per Melee: in energy form, two magic spells or seven psionic attacks/seven other actions per melee; in physical humanoid form, eight physical and/or psionic attacks/actions per melee, or two by magic. Critical strike from behind and on 18+, paired weapons, death blow; +10 save vs horror factor; +7 save vs magic; spell strength 16; +5 save vs psionics; +6 save vs poison.', NULL, 'All skills from the Wilderness and Military categories at 85%, plus all lore skills, climb, swim, dance, sing, cook, basic math, track humanoids, escape artist, intelligence, streetwise, prowl, roping, horsemanship: Cowboy, and horsemanship: exotic animals, all at 75% (several from Rifts New West). Magically understands/speaks all languages at 90%; literate in all Native American languages and English. O.C.C.: Not applicable.', 'Nightvision 2,000 ft; bio-regeneration 1D4x10/melee; impervious to poison and disease. Spirit Warrior abilities: vibration sense, flight (75 mph), invisibility, danger sense, chameleon, healing touch, and see invisible. Materialization into her original Native American human form or any owl. Possession of any owl or willing worshippers/comatose humans; adds 1D6x1000 S.D.C. to a possessed creature. Summons Lesser Animal Spirits and Greater Owl Totem Spirits. Special Awareness (see aura, sense evil, sixth sense, empathy all constantly active, no I.S.P. cost).', 'All Shamanic Spirit and Paradox spells, plus befuddle, fingers of wind, blind, mute, water to wine, fool''s gold, calling, domination, compulsion, agony, life drain, apparition, hallucination, luck curse, minor curse, curse: phobia, spoil (food and water), sickness, negate magic, repel animals, time slip, teleport: lesser, teleport: superior, mystic portal, time hole, close Rift and dimensional portal. Fetish abilities: none.', 'All physical and sensitive psionic powers, plus the super abilities Bio-Manipulation, empathic transmission, mind bond, mind block auto-defense, and psi-sword.', NULL, NULL, 'A pair of War Club Spirit Fetishes, one with a sullen face and one with a grinning face.', NULL, 'A young Shaman elevated to godhood by the other gods to avenge her massacred tribe; delivers ''Bad Medicine'' and death only to those who violate the Circle of Life, following a strict personal code of honor and fair play ("turn about is fair play"); sometimes blinded by her lust for vengeance and feels lonely and detached from other beings, including the other gods.', 'Tends to work alone or with animal spirits and Owl Totem spirits; occasionally works with other Native American gods and spirits; worshipped by many Native Americans as protector and avenger.', 'Evil and murderous forces. Uktena and his kind torment her and try to corrupt her, and she presses harder than any god for the serpent''s destruction. She counts the Coalition States'' rulers as manipulators, and grieves over the most vengeful Federation of Magic factions - whose hatred mirrors her own - above all their plan to enslave greater spirits.', 'The youngest of the Native American gods, an avenging spirit of death and bad medicine associated with the owl.', 'Rifts World Book 15: Spirit West p.180-182');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'strong-eagle', 'Strong Eagle', NULL, 'The War God', 'rifts', NULL, 'Effectively a 22nd level Totem Warrior and Wilderness Scout, and 9th level Ley Line Walker', 22, 'Scrupulous', 'Immortal, but can be destroyed while in energy form.', '6 feet tall in normal human form, or a 20 foot (6 m) giant', '200 pounds (90 kg) in human form, 10 tons as a giant', '{"IQ":19,"ME":23,"MA":18,"PS":55,"PP":28,"PE":29,"PB":19,"Spd":152}', 7600, 7000, NULL, 1500, 500, 14, 15, '{"initiative":6,"strike":10,"parry":12,"dodge":10,"roll":5,"pull":6,"disarm":5,"entangle":5}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals his combined H.P. + S.D.C.; see also Materialization Notes for the reduced ''ordinary human'' form. All physical attributes are supernatural; Spd 152 is 105 mph/168 km running. The book separately prints ''Horror Factor: 13 normally, 17 as a gore covered giant'', which conflicts with the ''Horror/Awe Factor: 15'' given with his main stats -- both are reported here, horror_factor set to the primary 15. Combat Attacks per Melee: in energy form, two magic spells or eight psionic attacks/eight other actions per melee; in physical humanoid form, 10 physical and/or psionic attacks/actions per melee, or two by magic. Paired weapons, critical strike from behind and on 18+, knockout from behind and on 17+, death blow; +7 save vs horror factor; +8 save vs magic and poison; spell strength 14; +5 save vs psionics. Rate of fire with the Spirit Bow is 8/melee round and +6 to strike with it; quick-draw rifle/pistol as the Gunfighter O.C.C. in Rifts New West.', '[{"name":"Recognize a specific person''s scent","pct":50},{"name":"Track by smell alone","pct":65}]', 'All skills from the Wilderness, Espionage and Military categories at 95%, plus all lore skills, boxing, wrestling, acrobatics, climb, swim, dance, sing, cook, basic math, horsemanship: knight, horsemanship: exotic animals, and trick riding, all at 85% (several from Rifts New West). Magically understands/speaks all languages at 98%; literate in all Native American languages, Spanish, English and Dragonese. O.C.C.: Not applicable.', 'Keen hawk-like telescopic vision (2 mi); keen sense of smell; nightvision 4000 ft; ambidextrous; double jointed; bio-regeneration 1D6x10/melee; impervious to cold, disease and fatigue; heals 3x normal rate. Supernatural Shapechanging: becomes any animal at 2-4x normal size (Totem Warrior bonuses apply), or an ordinary human (93 H.P., 50 S.D.C., no magic powers, but unchanged attributes/combat/bonuses) to experience mortality -- if that human form is destroyed his spirit is thrown back to the Spirit Realm at half M.D.C. Materialization into human appearance, a giant Native American warrior, or any animal. Possession of any animal or willing worshippers/comatose humans; adds 2D6x1000 S.D.C. to a possessed creature. Summons Lesser Animal Spirits and a Greater Totem Spirit. Can use white man''s energy weapons, body armor, jet packs, hovercycles, explosives, magic weapons/items and Techno-Wizard devices, especially in disguise.', 'All Shamanic Spirit and Animal spells; all sorcerous magic spells levels 1-6; plus second sight, exorcism, banishment, control/enslave entity, familiar link, all summon/control animal spells, close Rift, and dimensional portal. Can create/empower Armor, Weapon, Tooth and Claw, and tattoo fetishes only.', 'All Sensitive, Physical, and Super psionic abilities.', NULL, NULL, 'A Spirit knife, huge war club, tomahawk, and a bow -- each a Legendary Spirit Weapon fetish; also uses a major wing fetish to fight Xiticix.', NULL, 'The Native gods'' war god and champion: a patient planner who seldom starts a war but answers invaders, seeks out worthy opponents, and spares the brave, women and children while fighting outsiders by their own rules. Homeless by choice, he roams the Spirit Realm, Rifts Earth, Wormwood and beyond hunting monsters - above all the Xiticix that prey on the Sioux.', 'Other Native American gods, animal and Totem spirits, and many human/nonhuman warriors he deems worthy allies, plus the Native American people in general.', 'All who threaten the Spirit Realm or the gods, and the forces of evil generally; kills Two-Faced Star-People on sight and vampire lords, and despises Uktena, whom he has repeatedly challenged to a fight to the death.', 'The war god and champion-protector of the Native American gods and their Spirit Realm.', 'Rifts World Book 15: Spirit West p.182-185');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'spider-woman', 'Spider Woman', NULL, 'The Deep Earth Goddess', 'rifts', NULL, 'Equivalent of a 27th level Fetish Shaman and 15th level Earth Warlock and Ley Line Walker', 27, 'Unprincipled', 'Immortal, but can be destroyed while in energy form.', '5 feet, 7 inches (1.65 m) in human guise', '145 pounds (65 kg) in human guise', '{"IQ":27,"ME":28,"MA":30,"PS":30,"PP":24,"PE":26,"PB":11,"Spd":20}', 8300, 3900, NULL, 9600, 650, 14, 14, '{"strike":7,"parry":8,"dodge":8,"roll":4,"damage":4}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals her combined H.P. + S.D.C. All physical attributes are supernatural. P.B. 11 is for her old-woman form only; as a natural shapeshifter she can assume any P.B. up to 30. Horror/Awe Factor 14 is described as strictly an ''awe'' factor -- ''she is never horrible.'' Combat Attacks per Melee: in energy form, two magic spells or six psionic attacks/six other actions per melee; in physical humanoid form, six physical and/or psionic attacks/actions per melee, or three by magic. Critical strike from behind and on 19+, knockout from behind; +8 save vs horror factor; +9 save vs magic; spell strength 16; +6 save vs psionics; +10 save vs poison. No initiative bonus is printed for her.', NULL, 'All skills from the Wilderness, Domestic, Medicine and Science categories at 98%, plus all lore skills, climb, swim, basic and advanced math, all at 90%. Magically understands/speaks all languages at 98%; literate in all Native American languages, English, Euro, Spanish and Dragonese. O.C.C.: Not applicable.', 'Keen hawk-like telescopic vision (2 mi), keen smell and hearing, nightvision 6000 ft, ambidextrous; bio-regeneration 1D6x10/melee; impervious to cold, vacuum, radiation, disease and fatigue. Shapeshifts in one melee action into any insect, arachnid or mammal (including any human race), normal size for the species, taking half damage from her supernatural P.S. when smaller than a badger/raccoon. Possession of any plant, insect, arachnid or mammal (including humans); adds 4D4x1000 S.D.C. to a possessed creature. Summons Lesser Animal Spirits and a Greater Totem Spirit (of any kind, favoring spiders).', 'All Shamanic spells; all Earth Warlock spells levels 1-8; all conventional spells levels 1-15. Unequaled in fetish making: minor fetishes at one per hour, a major fetish in one day, Legendary fetishes in 1-4 weeks (only one class at a time); makes fetishes only for truly worthy humans, Great Spirits and fellow gods.', 'All Sensitive, Healing, and Super psionic abilities. Natural Telepath: unlimited use, no I.S.P. cost, 1 mile radius.', NULL, NULL, 'Can make any fetish she needs; normally has 1D20 fetishes on hand, rarely more than three legendary fetishes at once.', NULL, 'One of the oldest Native American deities, believed to be the first god and grandmother of the pantheon; moves slowly and avoids exertion, preferring magic, trickery and allies to direct action, and prefers to work as a puppet-master behind the scenes. If captured in an animal or insect form she cannot escape, shift shape, or use spells/psionics until rescued.', 'Other Native American gods, spirits (lesser and greater), and Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'The Splugorth and all alien intelligences, forces of evil, dark spirits, evil Shamans, supernatural monsters, and rivals; counted among gods who see Uktena as a symbol of death, and has clashed with the creature in the past.', 'The deep-earth goddess and eldest of the Native American deities, unequaled in the art of fetish making.', 'Rifts World Book 15: Spirit West p.185-186');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'god-thunderbird', 'The God Thunderbird', NULL, 'The Great God of the Air', 'rifts', NULL, 'Equivalent of a 25th level Warrior and 10th level Ley Line Walker', 25, 'Principled', 'Immortal, but can be destroyed while in energy form, though damage must exceed 1000 points below zero or the spirit recovers.', NULL, 'Not applicable to energy form', '{"IQ":18,"ME":21,"MA":17,"PS":48,"PP":22,"PE":26,"PB":25,"Spd":44}', 4300, 3800, NULL, 1300, 300, 15, 15, '{"attacks":9,"initiative":6,"strike":5,"parry":8,"dodge":8,"roll":5,"pull":6}', 'M.D.C. (when a materialized body is made on Rifts Earth) equals his combined H.P. + S.D.C. Physical attributes are considered supernatural. Size: 40 foot (12.2 m) tall fiery bird, 80 foot (24.4 m) wingspan. Spd is printed as two figures: 44 (30 mph/48 km) on the ground and 203 (200 mph/321 km) flying; 44 is used for attributes.Spd here. Combat Attacks per Melee: in energy form, two magic spells or nine psionic and/or physical attacks -- this is the single figure used for combat.attacks. Critical strike on 17+; +9 save vs horror factor; +6 save vs magic; spell strength 14; +4 save vs psionics; +5 save vs poison. Also known as the Great Thunderbird and "The" Thunderbird; god-king of the Ondi Thunderbirds.', NULL, 'All Wilderness, lore and math skills at 94%, plus track humanoids, intelligence, interrogation, sing, and climb, each at 90%, and prowl (in flight) 80%. Magically understands/speaks all languages at 90%; literate in Dragonese. O.C.C.: Not applicable.', 'Sees all light spectrums including infrared/ultraviolet; nightvision 5 miles; telescopic vision (2 mi); sees the invisible; keen hearing; bio-regenerates 2D4x10/melee; does not breathe; impervious to electricity, poisons, gases, drugs, disease and fatigue; other energy attacks (plasma, M.D. fire, ion blasts, particle beams, lasers) do half damage, but magic, magic weapons, Spirit weapons/fetishes and explosions do full damage. Lightning Transformation: becomes a bolt of lightning, travels roughly 4,400 mph/Mach 6.5, up to 1000 miles in one minute, P.P.E. cost 80. Modulating Damage: deals S.D.C./hit point damage to S.D.C. opponents and M.D. to mega-damage opponents. Aura of Light (as Bright Sky''s, 30 ft radius, save vs magic or be blinded). Materialization into a large ordinary-looking eagle or his natural crackling-energy giant-eagle form; unlike most energy beings he can physically grab, hold and strike both physical and ethereal targets. Possession of eagles only; adds 1D6x1000 S.D.C. to a possessed creature. Summons Ondi Thunderbirds and Elemental Spirits (Lesser or Greater). Vulnerable: cold- and water-based M.D.C. attacks do double damage.', 'All Ley Line Walker abilities and spells levels 1-8, plus summon fog, summon rain, summon storm, close Rift, and dimensional portal.', 'All sensitive and healing psionic abilities.', NULL, NULL, NULL, NULL, 'One of under a dozen primal Thunderbird gods still alive (three of the rest are diabolic, one anarchist); patient and shrewd, he studies every option before he acts. A founding ally of the Native gods and god-king of the Ondi Thunderbirds, who share his home on Thunder Peak in the Spirit Realm.', 'Ondi Thunderbirds, most Native American gods, some spirits, the occasional Temporal Raider, and Native American people in general, particularly Pure Ones and devoted Traditionalists.', 'Loathes Uktena and his minions (though he defers to allied gods who oppose killing it); also the Splugorth, the Aztec gods, and evil Thunderbird gods of his own kind; generally battles enemies of the Native American gods and supernatural evil.', 'An ancient, primal god of the air and living lightning, god-king of the Ondi Thunderbirds.', 'Rifts World Book 15: Spirit West p.187-189');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
  ('notable_npc', 'old-flame-dancing', 'Punch/Kick/Head Butt/Tail Swipe (Fire Snake or Giant form)', '+3D6 fire damage bonus', 1, 'melee', 'M.D. or S.D.C. depending on opponent', 0),
  ('notable_npc', 'old-flame-dancing', 'Fiery Snake Bite', '+4D6 extra damage', 1, 'melee', 'M.D. or S.D.C. as the situation/opponent warrants', 1),
  ('notable_npc', 'ever-tide', 'Bite (Water Crocodile form)', '2D4x10', 1, 'melee', 'M.D. or S.D.C./H.P. depending on environment', 0),
  ('notable_npc', 'ever-tide', 'Tail Slash (Water Crocodile form)', '2D6x10', 1, 'melee', 'M.D. or S.D.C./H.P. depending on environment', 1),
  ('notable_npc', 'standing-mountain', 'War Club Chasm', '1D4x10 M.D.', 1, 'opens a 75 ft long, 20 ft wide, 30 ft deep chasm', 'Target must save vs magic or fall in as it slams shut on the next action; usable once per melee round, up to three times a day; alternatively summons a Lesser Earth Elemental Spirit', 0),
  ('notable_npc', 'whispering-maiden', 'Icy Wind', '1D4 S.D.C.', 0, NULL, '-2 to initiative and alertness', 0),
  ('notable_npc', 'whispering-maiden', 'Hammering Wind Blast', '1D6 S.D.C.', 0, NULL, '-2 to initiative; 01-60% chance of temporarily blinding an unprotected target for 1D4 melee rounds (-9 to all combat rolls)', 1),
  ('notable_npc', 'beautiful-rock-dancer', 'Cold Blast (giant crystal form)', '3D6', 1, '1000 feet (305 m)', 'S.D.C. or M.D.C. depending on the target; can also lower temperature in a 1 mile/1.6 km radius by 50 degrees.', 0),
  ('notable_npc', 'beautiful-rock-dancer', 'Punch/Kick (giant crystal form)', 'Supernatural P.S. plus 2D6', 1, 'melee', NULL, 1),
  ('notable_npc', 'bright-sky', 'Fire/Plasma Bolt', '1D6x10', 1, '3000 feet (910 m)', 'S.D.C./M.D. depending on target; part of Unleash Energy.', 0),
  ('notable_npc', 'bright-sky', 'Laser Beam', '1D4x10', 1, '4000 feet (1200 m)', 'S.D.C./M.D. depending on target; part of Unleash Energy.', 1),
  ('notable_npc', 'bright-sky', 'Radiation or Microwave Blast', '6D6', 1, '1000 feet (305 m)', 'S.D.C./M.D. depending on target; part of Unleash Energy.', 2),
  ('notable_npc', 'bright-sky', 'Punch/Kick (giant warrior form)', 'Supernatural P.S. plus 20', 1, 'melee', NULL, 3),
  ('notable_npc', 'strong-eagle', 'Punch/Kick (giant form)', 'Supernatural P.S. plus 12', 1, 'melee', NULL, 0),
  ('notable_npc', 'god-thunderbird', 'Touch (energy form)', '4D6', 1, 'touch', 'M.D. on Rifts Earth; also knocks the target back 2D6 yards/meters, who loses initiative and two melee actions.', 0),
  ('notable_npc', 'god-thunderbird', 'Bite', '2D4x10', 1, 'melee', NULL, 1),
  ('notable_npc', 'god-thunderbird', 'Claws', 'Supernatural P.S. plus 12', 1, 'melee', NULL, 2),
  ('notable_npc', 'god-thunderbird', 'Lightning Dive', '1D6x100', 1, '20 foot (6 m) diameter', '+4 to strike in this form; can also strike harmlessly if he chooses. P.P.E. cost 20.', 3),
  ('notable_npc', 'god-thunderbird', 'Unleash Energy (electricity bolts from talons/eyes/mouth)', '4D6 to 1D6x10', 1, '4000 feet (1200 m)', 'Damage precisely controlled by the god; M.D. on Rifts Earth; one blast per melee attack/action.', 4),
  ('notable_npc', 'god-thunderbird', 'Electrical Field', '1D4x10 per melee round', 1, '100 foot (30.5 m) radius', 'Affects everyone in range; failing a save of 16+ dazes the victim (half combat bonuses/speed/skills/attacks); 01-75% chance to fry electrical devices (01-40% for those inside robots/war machines) and disrupt communications; the god can maintain it indefinitely but performs no other attacks while doing so.', 5);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 16 notable NPCs are in' AS assertion, count(*) AS got, 16 AS want
  FROM notable_npcs WHERE slug IN ('kacha-nesha', 'kacha-ani', 'kachir-hadu', 'kachir-nil', 'old-flame-dancing', 'ever-tide', 'standing-mountain', 'uktena', 'whispering-maiden', 'beautiful-rock-dancer', 'bright-sky', 'he-who-gives-life', 'she-who-walks-the-circle', 'strong-eagle', 'spider-woman', 'god-thunderbird');
SELECT 'and their 20 attacks' AS assertion, count(*) AS got, 20 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('kacha-nesha', 'kacha-ani', 'kachir-hadu', 'kachir-nil', 'old-flame-dancing', 'ever-tide', 'standing-mountain', 'uktena', 'whispering-maiden', 'beautiful-rock-dancer', 'bright-sky', 'he-who-gives-life', 'she-who-walks-the-circle', 'strong-eagle', 'spider-woman', 'god-thunderbird');

